const isAn=c=>!!c&&(c.tier===2||c.tier===3),ek=c=>c.tier*10+c.kind;
function epicLive(k){if(k<20)k+=20;let L=ELIVE[k];if(L)return L;const tl=(k>=30?LEG:EPIC)[k%10],cv=document.createElement('canvas');cv.width=EW*ESC;cv.height=EH*ESC;const ctx=cv.getContext('2d');ctx.scale(ESC,ESC);
  const off=document.createElement('canvas');off.width=EW*ESC;off.height=EH*ESC;const oc=off.getContext('2d');oc.scale(ESC,ESC);const st={};
  const M=s=>function(){s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};
  try{tl.bg(oc,M((k%10)*977+(k>=30?31:13)),st)}catch(e){console.error(e)}L=ELIVE[k]={cv,ctx,off,st,tl,last:-1};epicDraw(k,1.5);return L}
