function cover(q,src,dx,dy,dw,dh){const sw=src.width,sh=src.height,r=Math.max(dw/sw,dh/sh),w=dw/r,h=dh/r;q.drawImage(src,(sw-w)/2,(sh-h)/2,w,h,dx,dy,dw,dh)}
