C39.draw2=function(q,bx,by,bw,bh){const c=cur();if(!isAn(c))return false;try{q.save();q.globalAlpha=.92;cover(q,epicTick(ek(c)),bx,by,bw,bh);q.restore();return true}catch(e){return false}};
let PAD3=null;
